import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.lxr64Vqo.js";const p=JSON.parse('{"title":"Getting Started with NoxMedia","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1795112636000}'),i={name:"guide/getting-started.md"};function n(s,e,d,l,c,g){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="getting-started-with-noxmedia" tabindex="-1">Getting Started with NoxMedia <a class="header-anchor" href="#getting-started-with-noxmedia" aria-label="Permalink to &quot;Getting Started with NoxMedia&quot;">​</a></h1><p>Welcome to <strong>NoxMedia</strong> — a self-hosted personal streaming server that converts your Telegram channels and cloud media into a high-performance local media server compatible with <strong>Infuse</strong>, <strong>Stremio</strong>, <strong>Nuvio</strong>, and <strong>Android TV</strong>.</p><hr><h2 id="🌟-what-makes-noxmedia-different" tabindex="-1">🌟 What makes NoxMedia different? <a class="header-anchor" href="#🌟-what-makes-noxmedia-different" aria-label="Permalink to &quot;🌟 What makes NoxMedia different?&quot;">​</a></h2><p>Traditional media servers require massive hard drives and constant file downloads. NoxMedia operates on an on-demand streaming architecture:</p><ul><li><strong>Zero Local Storage Waste:</strong> Stream directly from cloud telegram storage into your favorite media players.</li><li><strong>Universal Client Support:</strong> Connect from Apple TV via <strong>Infuse</strong>, from Windows/Mac/Linux via <strong>Stremio</strong>, or from mobile via <strong>Nuvio</strong>.</li><li><strong>Hardware-Decoded DirectPlay:</strong> No server-side transcoding required. Your player decodes high-bitrate 4K, HDR, Dolby Vision, and Atmos natively.</li></ul><hr><h2 id="📋-prerequisites" tabindex="-1">📋 Prerequisites <a class="header-anchor" href="#📋-prerequisites" aria-label="Permalink to &quot;📋 Prerequisites&quot;">​</a></h2><ol><li>An Android device (Phone, Tablet, or Android TV / Google TV / Shield TV) running <strong>Android 7.0 (Nougat) or newer</strong>.</li><li>A Telegram account with access to media channels containing your movies and series.</li><li>Your own free <strong>Telegram API ID &amp; Hash</strong> (detailed below).</li></ol><hr><h2 id="🚀-step-1-download-the-noxmedia-apk" tabindex="-1">🚀 Step 1: Download the NoxMedia APK <a class="header-anchor" href="#🚀-step-1-download-the-noxmedia-apk" aria-label="Permalink to &quot;🚀 Step 1: Download the NoxMedia APK&quot;">​</a></h2><p>Download the latest version corresponding to your device architecture from the <a href="https://github.com/TheAceOfficials/NoxMedia/releases/latest" target="_blank" rel="noreferrer">GitHub Releases</a>:</p><ul><li><strong>NoxMedia-arm64-v8a.apk</strong> <em>(Recommended)</em>: For modern 64-bit phones, tablets, and Google TV with Chromecast.</li><li><strong>NoxMedia-armeabi-v7a.apk</strong>: For older 32-bit devices and budget Android TV boxes (Mi Box, older Fire TV sticks).</li><li><strong>NoxMedia-universal.apk</strong>: Universal build containing all CPU architectures.</li></ul><hr><h2 id="🔑-step-2-get-your-telegram-api-credentials" tabindex="-1">🔑 Step 2: Get your Telegram API Credentials <a class="header-anchor" href="#🔑-step-2-get-your-telegram-api-credentials" aria-label="Permalink to &quot;🔑 Step 2: Get your Telegram API Credentials&quot;">​</a></h2><p>To stream media through MTProto, Telegram requires official developer API credentials (which are 100% free):</p><ol><li>Open your browser and navigate to <strong><a href="https://my.telegram.org" target="_blank" rel="noreferrer">my.telegram.org</a></strong>.</li><li>Log in with your Telegram account phone number and submit the confirmation code sent to your Telegram app.</li><li>Tap on <strong>API development tools</strong>.</li><li>Fill in an <strong>App title</strong> and <strong>Short name</strong> (e.g., <code>NoxMedia</code> and <code>nox</code>).</li><li>Tap <strong>Create application</strong>.</li><li>Copy your <strong><code>api_id</code></strong> (numbers) and <strong><code>api_hash</code></strong> (letters and numbers).</li></ol><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Keep your API Hash private. NoxMedia stores these keys locally in encrypted private storage on your device.</p></div><hr><h2 id="📱-step-3-sign-in-to-noxmedia" tabindex="-1">📱 Step 3: Sign in to NoxMedia <a class="header-anchor" href="#📱-step-3-sign-in-to-noxmedia" aria-label="Permalink to &quot;📱 Step 3: Sign in to NoxMedia&quot;">​</a></h2><ol><li>Launch the NoxMedia app on your Android device.</li><li>Enter your <strong><code>api_id</code></strong> and <strong><code>api_hash</code></strong> on the setup screen.</li><li>Enter your phone number with your country code (e.g., <code>+919876543210</code>).</li><li>Enter the verification code sent to your Telegram app.</li><li>If you have Two-Step Verification (cloud password) enabled, enter your password.</li></ol><hr><h2 id="📂-step-4-add-media-channels" tabindex="-1">📂 Step 4: Add Media Channels <a class="header-anchor" href="#📂-step-4-add-media-channels" aria-label="Permalink to &quot;📂 Step 4: Add Media Channels&quot;">​</a></h2><ol><li>Once logged in, tap on the <strong>Channels</strong> tab.</li><li>Select the channels containing your movies, TV shows, and anime.</li><li>NoxMedia will automatically index your messages, parse file names, detect multi-part episodes, and assign rich TMDB/TVDB posters and metadata.</li></ol><hr><h2 id="🌐-step-5-start-streaming" tabindex="-1">🌐 Step 5: Start Streaming <a class="header-anchor" href="#🌐-step-5-start-streaming" aria-label="Permalink to &quot;🌐 Step 5: Start Streaming&quot;">​</a></h2><p>Go to the <strong>Home</strong> tab and tap <strong>Start Server</strong>.</p><p>NoxMedia will display your local server address (e.g., <code>http://192.168.1.10:8096</code>). You can now connect your favorite players:</p><ul><li><a href="/NoxMedia/clients/infuse">🍎 Connect Apple TV &amp; iOS via Infuse</a></li><li><a href="/NoxMedia/clients/stremio-nuvio">🍿 Connect Stremio &amp; Nuvio</a></li><li><a href="/NoxMedia/clients/android-tv-kodi">📺 Connect Android TV &amp; Kodi</a></li></ul>',29)])])}const m=t(i,[["render",n]]);export{p as __pageData,m as default};
